import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:go_router/go_router.dart';\nimport '../providers/product_provider.dart';\nimport '../providers/cart_provider.dart';\nimport '../models/cart_item_model.dart';\nimport '../widgets/product_card.dart';\n\nclass HomeScreen extends ConsumerStatefulWidget {\n  const HomeScreen({Key? key}) : super(key: key);\n\n  @override\n  ConsumerState<HomeScreen> createState() => _HomeScreenState();\n}\n\nclass _HomeScreenState extends ConsumerState<HomeScreen> {\n  String _selectedCategory = 'Semua';\n  final List<String> categories = ['Semua', 'Kursi', 'Meja', 'Sofa', 'Lemari', 'Tempat Tidur'];\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('Hoomly'),\n        elevation: 0,\n        actions: [\n          IconButton(\n            icon: const Icon(Icons.search),\n            onPressed: () => context.push('/search'),\n          ),\n          IconButton(\n            icon: const Icon(Icons.shopping_cart),\n            onPressed: () => context.push('/cart'),\n          ),\n          IconButton(\n            icon: const Icon(Icons.person),\n            onPressed: () => context.push('/profile'),\n          ),\n        ],\n      ),\n      body: SingleChildScrollView(\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            // Search Bar\n            Padding(\n              padding: const EdgeInsets.all(16),\n              child: GestureDetector(\n                onTap: () => context.push('/search'),\n                child: Container(\n                  padding: const EdgeInsets.symmetric(horizontal: 12),\n                  decoration: BoxDecoration(\n                    color: const Color(0xFFF5F5F5),\n                    borderRadius: BorderRadius.circular(10),\n                    border: Border.all(color: const Color(0xFFECF0F1)),\n                  ),\n                  child: const Row(\n                    children: [\n                      Icon(Icons.search, color: Color(0xFF7F8C8D)),\n                      SizedBox(width: 12),\n                      Text(\n                        'Cari furnitur...',\n                        style: TextStyle(color: Color(0xFF7F8C8D)),\n                      ),\n                    ],\n                  ),\n                ),\n              ),\n            ),\n            // Featured Products\n            Padding(\n              padding: const EdgeInsets.symmetric(horizontal: 16),\n              child: Text(\n                'Produk Unggulan',\n                style: Theme.of(context).textTheme.headlineSmall,\n              ),\n            ),\n            const SizedBox(height: 12),\n            SizedBox(\n              height: 250,\n              child: ref.watch(featuredProductsProvider).when(\n                loading: () => const Center(child: CircularProgressIndicator()),\n                data: (products) => ListView.builder(\n                  scrollDirection: Axis.horizontal,\n                  padding: const EdgeInsets.symmetric(horizontal: 16),\n                  itemCount: products.length,\n                  itemBuilder: (context, index) {\n                    final product = products[index];\n                    return SizedBox(\n                      width: 180,\n                      child: ProductCard(\n                        product: product,\n                        onTap: () => context.push('/product/${product.id}'),\n                        onWishlistTap: () {},\n                      ),\n                    );\n                  },\n                ),\n                error: (error, st) => Center(child: Text('Error: $error')),\n              ),\n            ),\n            const SizedBox(height: 24),\n            // Categories\n            Padding(\n              padding: const EdgeInsets.symmetric(horizontal: 16),\n              child: Text(\n                'Kategori',\n                style: Theme.of(context).textTheme.headlineSmall,\n              ),\n            ),\n            const SizedBox(height: 12),\n            SingleChildScrollView(\n              scrollDirection: Axis.horizontal,\n              padding: const EdgeInsets.symmetric(horizontal: 16),\n              child: Row(\n                children: categories.map((category) {\n                  final isSelected = _selectedCategory == category;\n                  return Padding(\n                    padding: const EdgeInsets.only(right: 8),\n                    child: FilterChip(\n                      label: Text(category),\n                      selected: isSelected,\n                      onSelected: (selected) {\n                        setState(() => _selectedCategory = category);\n                      },\n                    ),\n                  );\n                }).toList(),\n              ),\n            ),\n            const SizedBox(height: 24),\n            // Popular Products\n            Padding(\n              padding: const EdgeInsets.symmetric(horizontal: 16),\n              child: Text(\n                'Produk Populer',\n                style: Theme.of(context).textTheme.headlineSmall,\n              ),\n            ),\n            const SizedBox(height: 12),\n            Padding(\n              padding: const EdgeInsets.symmetric(horizontal: 16),\n              child: ref.watch(popularProductsProvider).when(\n                loading: () => const Center(child: CircularProgressIndicator()),\n                data: (products) => GridView.builder(\n                  shrinkWrap: true,\n                  physics: const NeverScrollableScrollPhysics(),\n                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(\n                    crossAxisCount: 2,\n                    crossAxisSpacing: 12,\n                    mainAxisSpacing: 12,\n                    childAspectRatio: 0.75,\n                  ),\n                  itemCount: products.length,\n                  itemBuilder: (context, index) {\n                    final product = products[index];\n                    return ProductCard(\n                      product: product,\n                      onTap: () => context.push('/product/${product.id}'),\n                      onWishlistTap: () {},\n                    );\n                  },\n                ),\n                error: (error, st) => Center(child: Text('Error: $error')),\n              ),\n            ),\n            const SizedBox(height: 24),\n          ],\n        ),\n      ),\n    );\n  }\n}\n